battleFight=function(me,raw){stop();const enemy={name:raw.name||'相手',imageNumber:raw.imageNumber||1,core:raw.imageData||'',stats:raw.stats||initial()},a=stats(me),b=stats(enemy);let myHp=a[1].value,enemyHp=b[1].value,first=Math.random()<.5?'自分':'相手',order=first==='自分'?['自分','相手','自分','相手']:['相手','自分','相手','自分'],turn=0,logs=[];const stageEl=document.querySelector('#stage');stageEl.innerHTML='<div class="battle-arena"><section id="enemy" class="fighter enemy-fighter"><img src="'+img(enemy)+'"><h2>'+esc(enemy.name)+'</h2>'+statsHtml(enemy)+'<b class="hp-value" id="ehp">体力：'+enemyHp+'</b></section><div class="vs-mark">VS</div><section id="self" class="fighter self-fighter"><img src="'+img(me)+'"><h2>'+esc(me.name)+'</h2>'+statsHtml(me)+'<b class="hp-value" id="mhp">体力：'+myHp+'</b></section></div><div id="attackFx" class="attack-fx"></div><p id="battleText" class="battle-text">'+first+'が先攻</p><div id="log" class="battle-log-list"></div>';const enemyEl=document.querySelector('#enemy'),selfEl=document.querySelector('#self'),fx=document.querySelector('#attackFx'),text=document.querySelector('#battleText'),logEl=document.querySelector('#log');const hit=v=>Math.random()<([0,.5,.6,.7,.8,.9][v]||.5),critical=v=>v===1?1:Math.random()<.3?({2:1.5,3:2,4:2.5,5:3}[v]||1):1;const animateHp=(el,from,to)=>{const start=performance.now(),duration=700;el.classList.add('hp-hit');const tick=now=>{const p=Math.min(1,(now-start)/duration);el.textContent='体力：'+Math.round(from+(to-from)*p);if(p<1)requestAnimationFrame(tick);else setTimeout(()=>el.classList.remove('hp-hit'),180)};requestAnimationFrame(tick)};const step=()=>{if(turn>=4||myHp<=0||enemyHp<=0){const result=enemyHp===0?'勝利':myHp===0?'敗北':myHp>enemyHp?'勝利':myHp<enemyHp?'敗北':'引き分け';state.history.unshift({opponent:enemy.name,result,date:new Date().toISOString(),logs});save();stageEl.innerHTML='<div class="result-burst">'+result+'</div><p>'+logs.join('<br>')+'</p>'+(result==='勝利'&&enemy.core?'<img class="core-img" src="'+enemy.core+'">':'')+'<button class="btn purple" id="again">対戦画面へ戻る</button>';document.querySelector('#again').onclick=battle;return}const side=order[turn],mine=side==='自分',attacker=mine?selfEl:enemyEl,target=mine?enemyEl:selfEl,x=mine?a:b,ok=hit(x[2].value),mult=ok?critical(x[3].value):1,damage=ok?Math.round(x[0].value*mult):0,oldMine=myHp,oldEnemy=enemyHp;attacker.classList.add(mine?'attack-up':'attack-down');setTimeout(()=>attacker.classList.remove('attack-up','attack-down'),650);target.classList.add('shaking');setTimeout(()=>target.classList.remove('shaking'),650);if(mine)enemyHp=Math.max(0,enemyHp-damage);else myHp=Math.max(0,myHp-damage);animateHp(document.querySelector(mine?'#ehp':'#mhp'),mine?oldEnemy:oldMine,mine?enemyHp:myHp);fx.textContent=!ok?'ミス':mult>1?'会心！ -'+damage:'-'+damage;fx.className='attack-fx show';setTimeout(()=>fx.className='attack-fx',700);const line=side+'の攻撃：'+(ok?damage+'ダメージ':'ミス');logs.push(line);logEl.insertAdjacentHTML('afterbegin','<div>'+line+'</div>');text.textContent=line;turn++;setTimeout(step,3000)};setTimeout(step,900)};
battleFight=function(me,raw){stop();const enemy={name:raw.name||'相手',imageNumber:raw.imageNumber||1,core:raw.imageData||'',stats:raw.stats||initial()},a=stats(me),b=stats(enemy);let myHp=a[1].value,enemyHp=b[1].value,first=Math.random()<.5?'自分':'相手',order=first==='自分'?['自分','相手','自分','相手']:['相手','自分','相手','自分'],turn=0,logs=[];const statRow=(s,p)=>'<div class="stats battle-inline-stats">'+s.map((x,i)=>'<div class="stat '+(x.name==='体力'?'hp-stat':'')+'"><b>'+x.name+'</b><span id="'+p+i+'">'+x.value+'</span><div class="bar"><div class="fill" style="width:'+x.value*20+'%"></div></div></div>').join('')+'</div>';const stageEl=document.querySelector('#stage');stageEl.innerHTML='<div class="battle-arena"><section id="enemy" class="fighter enemy-fighter"><img src="'+img(enemy)+'"><h2>'+esc(enemy.name)+'</h2>'+statRow(b,'e')+'</section><div class="vs-mark">VS</div><section id="self" class="fighter self-fighter"><img src="'+img(me)+'"><h2>'+esc(me.name)+'</h2>'+statRow(a,'m')+'</section></div><div id="attackFx" class="attack-fx"></div><p id="battleText" class="battle-text">'+first+'が先攻</p><div id="log" class="battle-log-list"></div>';const enemyEl=document.querySelector('#enemy'),selfEl=document.querySelector('#self'),fx=document.querySelector('#attackFx'),text=document.querySelector('#battleText'),logEl=document.querySelector('#log');const hit=v=>Math.random()<([0,.5,.6,.7,.8,.9][v]||.5),critical=v=>v===1?1:Math.random()<.3?({2:1.5,3:2,4:2.5,5:3}[v]||1):1;const animateHp=(id,from,to)=>{const el=document.querySelector('#'+id),start=performance.now(),duration=700;el.parentElement.classList.add('hp-hit');const tick=now=>{const p=Math.min(1,(now-start)/duration);el.textContent=Math.round(from+(to-from)*p);if(p<1)requestAnimationFrame(tick);else setTimeout(()=>el.parentElement.classList.remove('hp-hit'),180)};requestAnimationFrame(tick)};const step=()=>{if(turn>=4||myHp<=0||enemyHp<=0){const result=enemyHp===0?'勝利':myHp===0?'敗北':myHp>enemyHp?'勝利':myHp<enemyHp?'敗北':'引き分け';state.history.unshift({opponent:enemy.name,result,date:new Date().toISOString(),logs});save();stageEl.innerHTML='<div class="result-burst">'+result+'</div><p>'+logs.join('<br>')+'</p>'+(result==='勝利'&&enemy.core?'<img class="core-img" src="'+enemy.core+'">':'')+'<button class="btn purple" id="again">対戦画面へ戻る</button>';document.querySelector('#again').onclick=battle;return}const side=order[turn],mine=side==='自分',attacker=mine?selfEl:enemyEl,target=mine?enemyEl:selfEl,x=mine?a:b,ok=hit(x[2].value),mult=ok?critical(x[3].value):1,damage=ok?Math.round(x[0].value*mult):0,oldMine=myHp,oldEnemy=enemyHp;attacker.classList.add(mine?'attack-up':'attack-down');setTimeout(()=>attacker.classList.remove('attack-up','attack-down'),650);target.classList.add('shaking');setTimeout(()=>target.classList.remove('shaking'),650);if(mine)enemyHp=Math.max(0,enemyHp-damage);else myHp=Math.max(0,myHp-damage);animateHp(mine?'e1':'m1',mine?oldEnemy:oldMine,mine?enemyHp:myHp);fx.textContent=!ok?'ミス':mult>1?'会心！ -'+damage:'-'+damage;fx.className='attack-fx show';setTimeout(()=>fx.className='attack-fx',700);const line=side+'の攻撃：'+(ok?damage+'ダメージ':'ミス');logs.push(line);logEl.insertAdjacentHTML('afterbegin','<div>'+line+'</div>');text.textContent=line;turn++;setTimeout(step,3000)};setTimeout(step,900)};
function showBattle(me,raw){
  stop();
  const enemy={name:raw.name||'相手',imageNumber:raw.imageNumber||1,core:raw.imageData||raw.core||'',trainer:raw.trainer||'',stats:raw.stats||initial()};
  const myStats=stats(me),enemyStats=stats(enemy);
  me.stats=myStats;
  enemy.stats=enemyStats;
  let myHp=myStats[1].value,enemyHp=enemyStats[1].value;
  const first=Math.random()<.5?'自分':'相手';
  const order=first==='自分'?['自分','相手','自分','相手']:['相手','自分','相手','自分'];
  let turn=0,finished=false;
  const logs=[];
  const statRow=(list,prefix)=>'<div class="battle-stat-row">'+list.map((s,i)=>'<div class="battle-stat '+(i===1?'battle-hp-stat':'')+'"><span class="battle-stat-name">'+s.name+'</span><strong id="'+prefix+'Value'+i+'">'+s.value+'</strong><div class="bar"><div id="'+prefix+'Bar'+i+'" class="fill" style="width:'+s.value*20+'%"></div></div></div>').join('')+'</div>';
  root.innerHTML='<div id="battleStage" class="battle-stage"><section id="enemyFighter" class="battle-fighter battle-enemy"><img src="'+img(enemy)+'" alt="'+esc(enemy.name)+'"><h2>'+esc(enemy.name)+'</h2>'+statRow(enemyStats,'enemy')+'</section><div class="battle-vs">VS</div><section id="myFighter" class="battle-fighter battle-self"><img src="'+img(me)+'" alt="'+esc(me.name)+'"><h2>'+esc(me.name)+'</h2>'+statRow(myStats,'my')+'</section><div id="battleDamage" class="battle-damage"></div></div><p id="battleProgress" class="battle-progress">'+first+'が先攻</p>';
  const progress=document.querySelector('#battleProgress');
  const damageFx=document.querySelector('#battleDamage');
  const hit=value=>Math.random()<([0,.5,.6,.7,.8,.9][value]||.5);
  const critical=value=>value===1?1:(Math.random()<.3?({2:1.5,3:2,4:2.5,5:3}[value]||1):1);
  const animateHp=(prefix,from,to)=>{const value=document.querySelector('#'+prefix+'Value1'),bar=document.querySelector('#'+prefix+'Bar1'),start=performance.now();value.parentElement.classList.add('battle-hp-hit');const tick=now=>{const p=Math.min(1,(now-start)/650);value.textContent=Math.round(from+(to-from)*p);bar.style.width=(Math.max(0,to)*20)+'%';if(p<1)requestAnimationFrame(tick);else setTimeout(()=>value.parentElement.classList.remove('battle-hp-hit'),180)};requestAnimationFrame(tick)};
  const finishBattle=()=>{
    if(finished)return;
    finished=true;
    if(myHp<enemyHp){
      state.monsters=state.monsters.filter(monster=>monster.id!==me.id);
      if(state.selected===me.id)state.selected=state.monsters.at(-1)?.id||null;
      fetch('/api/monsters?id='+encodeURIComponent(me.id),{method:'DELETE'}).catch(()=>{});
    }else if(enemyHp<myHp&&raw.id){
      fetch('/api/monsters?id='+encodeURIComponent(raw.id),{method:'DELETE'}).catch(()=>{});
    }
    const result=enemyHp===0&&myHp>0?'勝利':myHp===0&&enemyHp>0?'敗北':myHp>enemyHp?'勝利':myHp<enemyHp?'敗北':'引き分け';
    let growth='';
    if(result==='勝利'){
      const total=myStats.reduce((sum,s)=>sum+s.value,0);
      const choices=total<12?myStats.filter(s=>s.value<5):[];
      if(choices.length){const raised=choices[Math.random()*choices.length|0];raised.value++;growth=raised.name+'の値が1増えました';me.stats=myStats;const stored=state.monsters.find(m=>m.id===me.id);if(stored)stored.stats=myStats;api(me)}
    }
    const historyRecord={opponent:enemy.name,trainer:enemy.trainer||'不明',result,date:new Date().toISOString(),logs};
    if(result==='勝利'&&enemy.core){historyRecord.core=enemy.core;historyRecord.capturedAt=historyRecord.date}
    state.history.unshift(historyRecord);
    save();
    const core=result==='勝利'&&enemy.core?'<p class="battle-result-note">奪取したモンスターのコア画像</p><img class="battle-result-core" src="'+enemy.core+'" alt="奪取したモンスターのコア画像">':'';
    const message=result==='敗北'?'<p class="battle-result-note">負けてモンスターは死にました</p>':growth?'<p class="battle-result-note">'+growth+'</p>':'';
    root.innerHTML='<div id="battleResult" class="battle-result '+(result==='勝利'?'is-win':result==='敗北'?'is-lose':'is-draw')+'"><div class="battle-result-title">'+result+'</div>'+core+message+'<p class="battle-result-guide">画面をタップするとメイン画面に戻ります</p></div>';
    document.querySelector('#battleResult').onclick=main;
  };
  const step=()=>{
    if(turn>=4||myHp<=0||enemyHp<=0)return finishBattle();
    const mine=order[turn]==='自分',attacker=mine?document.querySelector('#myFighter'):document.querySelector('#enemyFighter'),target=mine?document.querySelector('#enemyFighter'):document.querySelector('#myFighter'),attackerStats=mine?myStats:enemyStats;
    const landed=hit(attackerStats[2].value),multiple=landed?critical(attackerStats[3].value):1,amount=landed?Math.max(1,Math.round(attackerStats[0].value*multiple)):0;
    attacker.classList.add(mine?'battle-charge-up':'battle-charge-down');
    setTimeout(()=>attacker.classList.remove('battle-charge-up','battle-charge-down'),650);
    setTimeout(()=>{
      const oldHp=mine?enemyHp:myHp;
      if(mine)enemyHp=Math.max(0,enemyHp-amount);else myHp=Math.max(0,myHp-amount);
      target.classList.add('battle-shake');
      setTimeout(()=>target.classList.remove('battle-shake'),650);
      damageFx.textContent=!landed?'ミス':multiple>1?'会心！ -'+amount:'-'+amount;
      damageFx.className='battle-damage show '+(mine?'hit-enemy':'hit-self');
      setTimeout(()=>damageFx.className='battle-damage',800);
      if(landed)animateHp(mine?'enemy':'my',oldHp,mine?enemyHp:myHp);
      const text=(turn+1)+'回目 '+(mine?'自分':'相手')+'の攻撃：'+(!landed?'ミス':(multiple>1?'会心・':'')+amount+'ダメージ');
      logs.push(text);progress.textContent=text;
      turn++;
      setTimeout(step,1900);
    },550);
  };
  setTimeout(()=>document.querySelectorAll('.battle-fighter').forEach(el=>el.classList.add('battle-ready')),850);
  setTimeout(step,1200);
}
fight=(me,raw)=>showBattle(me,raw);
document.addEventListener('click',event=>{if(event.target?.id==='fictionalBattle'){event.stopImmediatePropagation();const me=sel()||{id:'preview',name:'自分のモンスター',imageNumber:1,core:'',stats:initial()};showBattle(me,{name:me.name,imageNumber:me.imageNumber,imageData:me.core||'',stats:stats(me).map(s=>({...s}))})}},true);
async function fetchBattleMonster(id){const response=await fetch('/api/monsters?id='+encodeURIComponent(id));if(!response.ok)throw new Error('monster not found');const data=await response.json();return {name:data.name||'相手',imageNumber:data.image_number||1,core:data.image_data||'',trainer:data.trainer||'',stats:typeof data.stats==='string'?JSON.parse(data.stats):data.stats}}
fight=async(me,raw)=>{if(raw?.id){try{return showBattle(me,await fetchBattleMonster(raw.id))}catch{return alert('モンスター情報を取得できませんでした。')}}return showBattle(me,raw)};
function prepareQr(monster){const payload={type:'amu-monster-battle',id:monster.id};monster.qrText=JSON.stringify(payload);monster.qrImageUrl='';return monster}
state.monsters.forEach(prepareQr);
const originalApi=api;api=async function(monster){prepareQr(monster);return originalApi(monster)};
const originalMakeQr=makeQR;makeQR=function(data){const box=document.querySelector('#qr');if(!box)return;box.innerHTML='';const text=JSON.stringify(data),fallback=sel()?.qrImageUrl||'https://api.qrserver.com/v1/create-qr-code/?size=190x190&data='+encodeURIComponent(text);if(typeof QRCode!=='undefined'){try{new QRCode(box,{text,width:190,height:190,colorDark:'#173b2b',colorLight:'#ffffff'});return}catch(e){}}const image=document.createElement('img');image.alt='対戦用QRコード';image.width=190;image.height=190;image.loading='eager';image.src=fallback;image.onerror=()=>{box.innerHTML='<p class="center">QRコードを生成できませんでした。もう一度開いてください。</p>';};box.appendChild(image)};
const qrLibraryReady=new Promise((resolve,reject)=>{if(typeof qrcode==='function')return resolve();const script=document.createElement('script');script.src='vendor/matrix-renderer.js?v=1';script.onload=()=>typeof qrcode==='function'?resolve():reject(new Error('QRライブラリ初期化失敗'));script.onerror=reject;document.head.appendChild(script)});
makeQR=function(data){const box=document.querySelector('#qr');if(!box)return;const text=JSON.stringify(data);box.innerHTML='<p class="center">QRコード生成中…</p>';const external=()=>{const image=document.createElement('img');image.alt='対戦用QRコード';image.width=220;image.height=220;image.loading='eager';image.src='https://api.qrserver.com/v1/create-qr-code/?size=220x220&data='+encodeURIComponent(text);image.onerror=()=>{box.innerHTML='<div class="qr-emergency"><strong>QRコードを表示できませんでした</strong><br><button class="btn gold" id="retryQr">QRを再生成</button></div>';document.querySelector('#retryQr').onclick=()=>makeQR(data)};box.innerHTML='';box.appendChild(image)};qrLibraryReady.then(()=>{try{const qrCode=qrcode(0,'M');qrCode.addData(text,'Byte');qrCode.make();box.innerHTML=qrCode.createImgTag(5,8);const image=box.querySelector('img');if(image){image.alt='対戦用QRコード';image.width=220;image.height=220;image.style.width='220px';image.style.height='220px';image.style.display='block'}}catch{if(typeof QRCode!=='undefined'){try{box.innerHTML='';new QRCode(box,{text,width:220,height:220,colorDark:'#000000',colorLight:'#ffffff'});return}catch{}}external()}}).catch(external)};
