battle=async function(){const me=sel();if(!me)return main();stop();await api(me);const own=me.battleCode||battleCode();me.battleCode=own;root.innerHTML='<button class="close" id="close">×</button><h1>コード読み取り画面</h1><section class="code-monster"><img src="'+img(me)+'" alt="'+esc(me.name)+'"><h2>'+esc(me.name)+'</h2><p>このモンスターの5桁コード</p><div class="battle-code-display">'+own+'</div></section><p class="center">相手の5桁コードを入力</p><div id="codeBoxes" class="verification-code"><input inputmode="numeric" maxlength="1"><input inputmode="numeric" maxlength="1"><input inputmode="numeric" maxlength="1"><input inputmode="numeric" maxlength="1"><input inputmode="numeric" maxlength="1"></div><p id="codeStatus" class="center">5桁そろうと自動で対戦を開始します。相手からの対戦も待受中です。</p>';document.querySelector('#close').onclick=main;const boxes=[...document.querySelectorAll('#codeBoxes input')],status=document.querySelector('#codeStatus');let starting=false;const monsterFrom=data=>({id:data.id,name:data.name,imageNumber:data.image_number||1,core:data.image_data||'',trainer:data.trainer||'',stats:typeof data.stats==='string'?JSON.parse(data.stats):data.stats});const start=async()=>{const code=boxes.map(box=>box.value).join('');if(starting||!/^\d{5}$/.test(code))return;starting=true;status.textContent='相手を確認しています…';try{const response=await fetch('/api/monsters',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'challenge',challengerId:me.id,targetCode:code})});if(!response.ok)throw 0;const data=await response.json();showSharedBattle(me,monsterFrom(data.monster),data.battle,data.role)}catch{starting=false;status.textContent='そのコードのモンスターが見つかりません。';boxes.forEach(box=>box.value='');boxes[0].focus()}};boxes.forEach((box,index)=>{box.oninput=()=>{box.value=box.value.replace(/\D/g,'').slice(-1);if(box.value&&index<4)boxes[index+1].focus();start()};box.onkeydown=event=>{if(event.key==='Backspace'&&!box.value&&index>0)boxes[index-1].focus()};box.onpaste=event=>{event.preventDefault();const digits=event.clipboardData.getData('text').replace(/\D/g,'').slice(0,5);digits.split('').forEach((digit,i)=>boxes[i].value=digit);start()}});boxes[0].focus();timer=setInterval(async()=>{if(starting)return;try{const response=await fetch('/api/monsters?waitingFor='+encodeURIComponent(me.id));if(response.status===204)return;if(!response.ok)return;const data=await response.json();starting=true;status.textContent='対戦を受け付けました。';showSharedBattle(me,monsterFrom(data.monster),data.battle,data.role)}catch{}},1000)};
function showSharedBattle(me,enemy,battleData,role){
  stop();
  if(!battleData||!Array.isArray(battleData.turns))return showBattle(me,enemy);
  const mySide=role==='target'?'target':'challenger',enemySide=mySide==='challenger'?'target':'challenger';
  const myStats=stats(me),enemyStats=stats(enemy);
  let myHp=Number(myStats[1]?.value||1),enemyHp=Number(enemyStats[1]?.value||1),turn=0;
  const logs=[];
  const statRow=(list,prefix)=>'<div class="battle-stat-row">'+list.map((s,i)=>'<div class="battle-stat '+(i===1?'battle-hp-stat':'')+'"><span class="battle-stat-name">'+esc(s.name)+'</span><strong id="'+prefix+'Value'+i+'">'+s.value+'</strong><div class="bar"><div id="'+prefix+'Bar'+i+'" class="fill" style="width:'+s.value*20+'%"></div></div></div>').join('')+'</div>';
  root.innerHTML='<div id="battleStage" class="battle-stage"><section id="enemyFighter" class="battle-fighter battle-enemy"><img src="'+img(enemy)+'" alt="'+esc(enemy.name)+'"><h2>'+esc(enemy.name)+'</h2>'+statRow(enemyStats,'enemy')+'</section><div class="battle-vs">VS</div><section id="myFighter" class="battle-fighter battle-self"><img src="'+img(me)+'" alt="'+esc(me.name)+'"><h2>'+esc(me.name)+'</h2>'+statRow(myStats,'my')+'</section><div id="battleDamage" class="battle-damage"></div></div><p id="battleProgress" class="battle-progress">'+(battleData.first===mySide?'自分':'相手')+'が先攻</p>';
  const progress=document.querySelector('#battleProgress'),damageFx=document.querySelector('#battleDamage');
  const setHp=(prefix,value)=>{const number=document.querySelector('#'+prefix+'Value1'),bar=document.querySelector('#'+prefix+'Bar1');if(number)number.textContent=value;if(bar)bar.style.width=Math.max(0,value)*20+'%'};
  const finish=()=>{
    const won=battleData.winnerId===me.id,draw=!battleData.winnerId,result=draw?'引き分け':won?'勝利':'敗北';
    if(!won&&!draw){state.monsters=state.monsters.filter(monster=>monster.id!==me.id);if(state.selected===me.id)state.selected=state.monsters.at(-1)?.id||null}
    const record={opponent:enemy.name,trainer:enemy.trainer||'不明',result,date:new Date().toISOString(),logs:[...logs]};
    if(won&&enemy.core){record.core=enemy.core;record.capturedAt=record.date}
    state.history.unshift(record);save();
    const captured=won&&enemy.core?'<p class="battle-result-note">奪取したモンスターのコア画像</p><img class="battle-result-core" src="'+enemy.core+'" alt="奪取したモンスターのコア画像">':'';
    const defeated=!won&&!draw?'<p class="battle-result-note">負けたモンスターは死亡しました。</p>':'';
    root.innerHTML='<div id="battleResult" class="battle-result '+(won?'is-win':draw?'is-draw':'is-lose')+'"><div class="battle-result-title">'+result+'</div>'+captured+defeated+'<p class="battle-result-guide">画面をタップするとメイン画面に戻ります</p></div>';
    document.querySelector('#battleResult').onclick=main;
  };
  const step=()=>{
    if(turn>=battleData.turns.length)return finish();
    const item=battleData.turns[turn],mine=item.attacker===mySide;
    const attacker=document.querySelector(mine?'#myFighter':'#enemyFighter'),target=document.querySelector(mine?'#enemyFighter':'#myFighter');
    attacker.classList.add(mine?'battle-charge-up':'battle-charge-down');
    setTimeout(()=>attacker.classList.remove('battle-charge-up','battle-charge-down'),600);
    setTimeout(()=>{target.classList.add('battle-shake');setTimeout(()=>target.classList.remove('battle-shake'),600);myHp=Number(mySide==='challenger'?item.challengerHp:item.targetHp);enemyHp=Number(enemySide==='challenger'?item.challengerHp:item.targetHp);setHp('my',myHp);setHp('enemy',enemyHp);damageFx.textContent=!item.landed?'ミス':Number(item.multiple)>1?'会心！ -'+item.damage:'-'+item.damage;damageFx.className='battle-damage show '+(mine?'hit-enemy':'hit-self');setTimeout(()=>damageFx.className='battle-damage',750);const line=(turn+1)+'回目 '+(mine?'自分':'相手')+'の攻撃：'+(!item.landed?'ミス':(Number(item.multiple)>1?'会心！ ':'')+item.damage+'ダメージ');logs.push(line);progress.textContent=line;turn++;setTimeout(step,1500)},500);
  };
  setTimeout(()=>document.querySelectorAll('.battle-fighter').forEach(el=>el.classList.add('battle-ready')),500);
  setTimeout(step,850);
}

history=function(){
  const monster=sel(),captures=Array.isArray(monster?.capturedCores)?monster.capturedCores:[],full=captures.length>=10;
  const formatDate=value=>{const date=new Date(value);if(Number.isNaN(date.getTime()))return '不明';const pad=n=>String(n).padStart(2,'0');return date.getFullYear()+'年'+(date.getMonth()+1)+'月'+date.getDate()+'日 '+pad(date.getHours())+'時'+pad(date.getMinutes())+'分'};
  const body=state.history.length?state.history.map((item,index)=>{const resultClass=item.result==='勝利'?'history-win':item.result==='敗北'?'history-lose':'history-draw';return '<article class="history"><b class="history-result '+resultClass+'">'+esc(item.result)+'</b>　'+esc(item.opponent)+'<br>トレーナー：'+esc(item.trainer||'不明')+'<br>'+esc(formatDate(item.date))+(item.core?'<p>奪取したコア画像</p><img class="core-img" src="'+item.core+'" alt="奪取したコア画像"><button class="btn '+(full?'save-disabled':'pink')+'" data-save-history-core="'+index+'" '+(full?'disabled':'')+'>保存する</button>':'')+'</article>'}).join(''):'<p class="center">まだ対戦履歴はありません。</p>';
  shell('対戦履歴',body);
  document.querySelectorAll('[data-save-history-core]').forEach(button=>button.onclick=async()=>{const index=Number(button.dataset.saveHistoryCore),entry=state.history[index],target=sel();if(!entry?.core||!target)return;if(!Array.isArray(target.capturedCores))target.capturedCores=[];if(target.capturedCores.length>=10)return;target.capturedCores.unshift({image:entry.core,trainer:entry.trainer||'不明',capturedAt:entry.capturedAt||entry.date});save();await api(target);history()});
};

core=function(){
  const monster=sel();
  if(!monster)return shell('奪取したコア画像','<p class="center">表示するモンスターがありません。</p>');
  const captures=Array.isArray(monster.capturedCores)?monster.capturedCores:[];
  const date=value=>{const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'不明':parsed.toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric'})};
  const capturedHtml=captures.length?'<section class="captured-core-list">'+captures.map((item,index)=>'<article class="captured-core"><img class="core-img" src="'+item.image+'" alt="奪取したコア画像"><p>相手トレーナー：'+esc(item.trainer||'不明')+'<br>対戦日：'+esc(date(item.capturedAt))+'</p><button class="btn gold" data-discard-capture="'+index+'">捨てる</button></article>').join('')+'</section>':'<p class="center">保存したコア画像はまだありません。</p>';
  shell('奪取したコア画像',capturedHtml);
  document.querySelectorAll('[data-discard-capture]').forEach(button=>button.onclick=async()=>{const index=Number(button.dataset.discardCapture);monster.capturedCores.splice(index,1);save();await api(monster);core()});
};

